UPDATE TB_CRAWL_RUN
   SET STATUS       = #{status}
     , ENDED_AT     = SYSDATE
     , PAGE_COUNT   = #{pageCount}
     , FETCHED_CNT  = #{fetchedCnt}
     , INSERTED_CNT = #{insertedCnt}
     , UPDATED_CNT  = #{updatedCnt}
     , FAILED_CNT   = #{failedCnt}
     , ERROR_MSG    = #{errorMsg}
 WHERE RUN_ID = #{runId}
   AND STATUS = 'RUNNING'

UPDATE TB_CRAWL_RUN
   SET PAGE_COUNT   = #{pageCount}
     , FETCHED_CNT  = #{fetchedCnt}
     , INSERTED_CNT = #{insertedCnt}
     , UPDATED_CNT  = #{updatedCnt}
     , FAILED_CNT   = #{failedCnt}
 WHERE RUN_ID = #{runId}
   AND STATUS = 'RUNNING'
